const themeSwitches=document.querySelectorAll("[data-color-theme-toggle]");function removeColorThemeLocalStorage(){localStorage.removeItem("color-theme")}function saveColorTheme(colorTheme){"system"!==colorTheme?localStorage.setItem("color-theme",colorTheme):removeColorThemeLocalStorage()}function applyColorTheme(){const localStorageColorTheme=localStorage.getItem("color-theme"),colorTheme=localStorageColorTheme||null;colorTheme&&document.documentElement.setAttribute("data-color-theme",colorTheme)}function themeSwitchHandler(){themeSwitches.forEach(themeSwitch=>{const el=themeSwitch;el.value===localStorage.getItem("color-theme")&&(el.checked=!0),el.addEventListener("change",()=>{"system"!==el.value?(saveColorTheme(el.value),applyColorTheme(el.value)):(removeColorThemeLocalStorage(),document.documentElement.removeAttribute("data-color-theme"))})}),applyColorTheme()}document.addEventListener("DOMContentLoaded",()=>{themeSwitchHandler(),applyColorTheme()});